**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <algorithm>
using namespace std;

int gcd(int a, int b) {
    while (b) { int t = b; b = a % b; a = t; }
    return a;
}

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    int maxDl = 0, maxStart = 0, maxNwd = 0;

    for (int i = 0; i < n; i++) {
        int curNwd = T[i];
        for (int j = i; j < n; j++) {
            curNwd = gcd(curNwd, T[j]);
            if (curNwd == 1) break;
            int dl = j - i + 1;
            if (dl > maxDl) {
                maxDl = dl;
                maxStart = i;
                maxNwd = curNwd;
            }
        }
    }

    cout << "a) Dlugosc: " << maxDl
         << ", pozycja poczatkowa: " << maxStart + 1 << endl;
    cout << "b) NWD: " << maxNwd << endl;
    cout << "c) Elementy:";
    for (int i = maxStart; i < maxStart + maxDl; i++)
        cout << " " << T[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Dla kazdego poczatku i, rozszerzamy podciag obliczajac NWD przyrostowo. Gdy NWD spadnie do 1, przerywamy (dalsze rozszerzanie nie pomoze). Sledzenie najdluzszego podciagu z NWD > 1.

Weryfikacja (dane: 7,6,10,8,14,4,9,15,21,3,5,11):
- i=0: nwd=7. j=0: dl=1, nwd=7>1. j=1: nwd=gcd(7,6)=1. Stop.
- i=1: nwd=6. j=1: dl=1. j=2: nwd=gcd(6,10)=2. j=3: gcd(2,8)=2. j=4: gcd(2,14)=2. j=5: gcd(2,4)=2. dl=5. j=6: gcd(2,9)=1. Stop. maxDl=5, maxStart=1, maxNwd=2.
- i=2: nwd=10. j=2: dl=1. j=3: gcd(10,8)=2. j=4: gcd(2,14)=2. j=5: gcd(2,4)=2. dl=4. j=6: gcd(2,9)=1. Stop. 4<5.
- i=3-5: podobnie, dl <= 3.
- i=6: nwd=9. j=6: dl=1. j=7: gcd(9,15)=3. j=8: gcd(3,21)=3. j=9: gcd(3,3)=3. dl=4. j=10: gcd(3,5)=1. Stop. 4<5.
- i=7-11: dl <= 3.

